const invalidated = $input.all().map((i) => i.json).filter((r) => r?.id);
return [{
  json: {
    success: true,
    found: false,
    source: 'wasender_api',
    synced: invalidated.length > 0,
    status: 'disconnected',
    connected: false,
    connection: invalidated[0] ?? null,
    wasender: null,
    message: 'No active Wasender session found. DB invalidated if stale row existed.',
  },
}];

const body = $('Webhook - unbind1').first().json.body ?? {};
const row = $('Postgres - lookup for unbind1').first().json ?? {};
const wasender_session_id = row.wasender_session_id ?? body.whatsappSession ?? body.wasender_session_id ?? null;
return [{
  json: {
    wasender_session_id,
    connection_id: row.id ?? null,
    owner_email: row.owner_email ?? body.owner_email ?? null,
    phone_number: row.phone_number ?? body.phone_number ?? null,
    had_db_row: !!row.id,
  },
}];

