const targets = $('Code - resolve unbind targets').first().json;
let disconnect = null;
let deleteSession = null;
try { disconnect = $('Wasender - disconnect (unbind)1').first().json; } catch (_) {}
try { deleteSession = $('Wasender - delete session (unbind)').first().json; } catch (_) {}
const deleted = $('Postgres - delete connection row').all().map((item) => item.json).filter((row) => row?.id);
return [{
  json: {
    success: true,
    status: 'removed',
    message: 'WhatsApp session disconnected, deleted from Wasender, and removed from database.',
    wasender_session_id: targets.wasender_session_id,
    deleted_count: deleted.length,
    deleted_connection: deleted[0] ?? null,
    wasender_disconnect: disconnect,
    wasender_delete: deleteSession,
  },
}];

const webhook = $('Webhook - Get possible contacts').first().json;
const conn = $input.first().json ?? {};
const body = webhook.body ?? webhook;
if (!conn?.api_key) {
  return [{ json: { success: false, error: 'No WhatsApp connection found. Pair your device first.' } }];
}
if (String(conn.status ?? '').toLowerCase() !== 'connected') {
  return [{ json: { success: false, error: `WhatsApp is not connected (status: ${conn.status ?? 'unknown'})` } }];
}
return [{ json: {
  api_key: conn.api_key,
  owner_email: conn.owner_email,
  phone_number: conn.phone_number,
  paginated: body.paginated ?? 'true',
  page: body.page ?? '1',
  limit: body.limit ?? '10',
} }];

