const webhook = $('Webhook - Get phone from lid').first().json;
const conn = $input.first().json ?? {};
const body = webhook.body ?? webhook;
if (!conn?.api_key) {
  return [{ json: { success: false, error: 'No WhatsApp connection found. Pair your device first.' } }];
}
if (String(conn.status ?? '').toLowerCase() !== 'connected') {
  return [{ json: { success: false, error: `WhatsApp is not connected (status: ${conn.status ?? 'unknown'})` } }];
}
if (!body.lid) {
  return [{ json: { success: false, error: 'Missing lid in request body.' } }];
}
return [{ json: { api_key: conn.api_key, lid: body.lid } }];
